<script setup>
import { computed, ref } from 'vue'

const props = defineProps({ applications: { type: Array, default: () => [] }, loading: Boolean })
const emit = defineEmits(['review', 'refresh'])
const activeTab = ref('pending')
const pendingApplications = computed(() => (Array.isArray(props.applications) ? props.applications : []).filter((item) => item?.status === 'pending'))
const historyApplications = computed(() => (Array.isArray(props.applications) ? props.applications : []).filter((item) => item?.status !== 'pending'))
</script>

<template>
  <section class="review-page">
    <article class="panel">
      <div class="review-toolbar"><div class="review-tabs" role="tablist"><button :class="{ active: activeTab === 'pending' }" type="button" @click="activeTab = 'pending'">待审核申请 <span>{{ pendingApplications.length }}</span></button><button :class="{ active: activeTab === 'history' }" type="button" @click="activeTab = 'history'">已处理申请 <span>{{ historyApplications.length }}</span></button></div><button class="text-button" type="button" @click="emit('refresh')">刷新</button></div>
      <div v-if="activeTab === 'pending'" class="tab-panel"><div v-if="!pendingApplications.length" class="pending-empty"><div class="empty-mark" aria-hidden="true">✓</div><strong>当前没有待审核申请</strong><span>新的组织加入申请会显示在这里，处理后将自动归档到“已处理申请”。</span><button class="refresh-button" type="button" @click="emit('refresh')">刷新申请</button></div><div v-for="application in pendingApplications" :key="application.id" class="review-row"><div class="applicant"><strong>{{ application.username }}</strong><small>申请加入 {{ application.organization_name }} · {{ new Date(application.created_at).toLocaleString() }}</small></div><span class="default-role">批准后仅加入组织，角色不变</span><div class="review-actions"><button class="approve" type="button" @click="emit('review', { id: application.id, approve: true })">批准</button><button class="reject" type="button" @click="emit('review', { id: application.id, approve: false })">拒绝</button></div></div></div>
      <div v-else class="tab-panel"><ul class="history"><li v-for="application in historyApplications" :key="application.id"><span><strong>{{ application.username }}</strong><small>{{ application.organization_name }}</small></span><em :class="application.status">{{ application.status === 'approved' ? '已批准' : '已拒绝' }}</em></li><li v-if="!historyApplications.length" class="muted">暂无已处理记录。</li></ul></div>
    </article>
  </section>
</template>

